+package com.pledgerio.app.identity.session
+
+class SessionManagerExtras(private val sessionManager: SessionManager) {
+    @Volatile private var cachedUsername: String? = null
+
+    fun cachedOrFetchUsername(): String? {
+        return cachedUsername ?: sessionManager.getUsername().also { cachedUsername = it }
+    }
+}
